from pathlib import Path
import json,hashlib,datetime
R=Path(__file__).resolve().parents[5];D=Path(__file__).resolve().parent;C=Path('/tmp/medina-source-cache/endocrinologie/E42')
assert not (D/'source-binding.json').exists(),'Final evidence sealed; never refresh automatically.'
rows=[]
def add(i,url,title,pub,version,file,section,pop,limits,note,level='section'):
 p=Path(file);p=p if p.is_absolute() else C/p
 assert p.is_file(),p
 rows.append(dict(id=i,url=url,titre=title,editeur=pub,version_annee=version,date_consultation='2026-11-02',section_page=section,population=pop,limites=limits,cache_external=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),lecteur='sol_endocrinologie',read_level=level,passage_paraphrase=note))
add('S1','https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686265/master','CIM-10-GM : libellé local suisse E42','OFS Suisse','2024',R/'nosology/fragments/S05.json','Entrée E42 locale, titre, code unique et version ; pas PDF intégral relu','Classification locale suisse','Source de métadonnées locale dérivée, pas relecture du PDF OFS intégral ni certification de codage2026.','E42 est intitulée Kwashiorkor avec marasme, dans E40–E46 ; un code unique sans subdivision locale. Le rapprochement PROFILES est explicitement pédagogique, pas mapping officiel.')
add('S2','https://klassifikationen.bfarm.de/icd-10-gm/kode-suche/htmlgm2024/block-e40-e46.htm','CIM-10-GM E40–E46 et définition E42','BfArM Allemagne','2024','bfarm2024.html','Notes du bloc et E40, E41, E42, E43 et exclusions','Classification allemande','Poids de référence et notes générales non assimilés à une nouvelle définition OMS ni à une prescription.','E42 inclut malnutrition protéino-énergétique grave intermédiaire ou signes simultanés de kwashiorkor et marasme. E40 et E41 excluent E42 ; E43 inclut œdème de famine sans précision, pas remplacement automatique d’une forme mixte documentée.')
add('S3','https://www.who.int/publications/i/item/9789240082830','Prevention and management of wasting and nutritional oedema under5','OMS Genève','2023','who2023.pdf','Glossairevii–ix ; introductionp6–8 ; A1–A7 ; B1–B10 ; p70–72,83–84 ; recommandations maintenuesp152–155','Moins5ans, schémas6–59mois distincts des moins6mois','Recommandations et certitudes variées. Pas protocole adulte, pas nouvelle norme2026. Texte paraphrasé seulement, pas figures OMS sous licenceNC réutilisées.','6–59mois : émaciation sévère poids/taille<−3 ou bras<115mm, et/ou œdème nutritionnel. Admission si danger, problème aigu, œdème+++ ou échec appétit. Transfert clinique distinct de sortie nutritionnelle, sortie exige deux mesures consécutives poids/taille≥−2 ET bras≥125 ET absence œdème. Deux options RUTF :150–185jusqu’à récupération, OU réduction100–130 seulement après disparition œdème et émaciation sévère, jusqu’à récupération. ReSoMal préféré sans choc, SRO faibleosmolarité possible si absent, surveillance en structure, SROnormal si choléra/diarrhéeprofuse. Moins6mois avec œdème hospitalisation, soutien allaitement, pasF100plein si instable/œdème.')
add('S4','https://medicalguidelines.msf.org/en/viewport/CG/english/severe-acute-malnutrition-16689141.html','Severe acute malnutrition : manuel clinique','Médecins Sans Frontières, Genève/France','Février2024','msf-sam2024.html','Chapitre1 : diagnostic, complications, phases, traitement, transfert/sortie','Enfants6–59mois seulement','Protocole opérationnel, pas FI suisse. Différence sortie : poids/taille>−2 OU bras>125 sur2semaines, tandis OMS2023 demandeET/deuxvisites ; ne pas fusionner.','Œdème bilatéral au godet après exclusion autres causes suffit à classification sévère ; bras gauche relâché, ruban sans compression. Infection peut être sans fièvre. Amoxicilline orale50mg/kgparprise,max1g,deuxfois/j5–7jours en routine sauf infection spécifique, différente de FI3–4prises. Nutriments spécialisés selon stabilité ; choc/sepsis nécessitent soins hospitaliers, pas seuls aliments ni amoxicillineorale. Hydratation réévaluée, surveiller surcharge, ne pas transposer chaque dose à toute population.')
add('S5','https://medicalguidelines.msf.org/en/viewport/EssDr/english/resomal-rehydration-solution-for-malnutrition-oral-16684569.html','ReSoMal oral : préparation et précautions','Médecins Sans Frontières','Novembre2022','msf-resomal.html','Indication, sachet, dilution, doses, contre-indications, conservation','Déshydratation dans malnutrition compliquée, surveillance médicale','Protocole externe non disponibilité/autorisation suisse établie. Doses diffèrent de schémas plus anciens et essais ; ne pas construire un débit composite.','Sachet84g pour2litres propres bouillis refroidis, solution24h ; ne pas injecter, ne pas concentrer. Choléra/malnutrition non compliquée : SROstandard. Débit suivi, surcharge/cardiopathie si trop rapide ; pas auto-administration familiale de ReSoMal selonOMS2023. Le texteMSF mentionne adulte/grossesse/allaitement, sans transformer protocole pédiatrique en prescription adulte universelle.')
add('S6','https://pmc.ncbi.nlm.nih.gov/articles/PMC7469063/','Acute Malnutrition in Children: Pathophysiology, Clinical Effects and Treatment','Dipasquale et coll., Italie','2020','dipasquale2020.xml','Corps sections1–5.3, tableaux1–2, conclusion ; source réellement relue','Revue pédiatrique','Revue ancienne avec références parfois discordantes et hypothèse simplecarenceprotéique/œdème trop réductrice. Ne pas adopter chiffres globaux anciens, irréversibilité cerveau3–4ans ou schéma45mg/kg/j comme norme actuelle.','Perte de tissu, adaptation métabolique, entéropathie et infections interagissent. Forme mixte = fonte et œdème simultanés. F75:75kcal/100ml,0,9gprotéines ; F100:100kcal/100ml,2,9g. Phase initiale prudente puis rattrapage, glucose/électrolytes/risque renutrition surveillés. Poids modifié par eau ; histoire, mesures sériées et terrain nécessaires.')
add('S7','https://pmc.ncbi.nlm.nih.gov/articles/PMC6947262/','Management of Refeeding Syndrome in Medical Inpatients','Reber et coll., Berne/Aarau Suisse','2019','reber2019.xml','Corps sections1–10 : mécanismes, périmètre, prévention, surveillance et limites','Patients médicaux hospitalisés, adultes, troublesalimentaires exclus','Pas protocole pédiatrique ni anorexie ; preuves souvent observationnelles. Ne pas recopier commentaire sodiumRinger imprécis ou toutes doses électrolytes sans FI propre.','Réalimentation peut déplacer phosphate,potassium,magnésium et révéler carence thiamine, avec surcharge et dysfonction d’organes. Chez adultes à risque : début5–15kcal/kg/j selonrisque, objectif5–10jours ; thiamine200–300mgau moins30min avant. Premières72h vulnérables, surveillancejusqu10jours. Ce n’est ni une dose infantile ni une raison de laisser persister une hypoglycémie urgente.')
add('S8','https://pmc.ncbi.nlm.nih.gov/articles/PMC13721215/','Multi-omics, multi-tissue analysis and edematous malnutrition','Nackers et coll., Niger/Belgique, MSF et universités','28octobre2026','nackers2026.xml','Résumé,introduction,méthodes/tableau1, résultats lipides/métabolites/intégrationfigure4, discussion/limites/conclusion','60enfants6–59mois par groupe, Niger2018–2019','Cas-témoins exploratoire, NAM parfois malades, pas validation indépendante, formes mixtes non distinguées du kwashiorkor. Associations, pas cause prouvée ni tests/prescriptions de routine.','Signatures protéines de matrice et sphingolipides diffèrent, suivent sévérité œdème et traitement. Albumine seule n’explique pas tout ; microbiome et métabolome non spécifiques dans analyses peu puissantes. Matrice/lymphatiques et inflammation sont hypothèses plausibles, pas raison de perfuser albumine ou donner un supplément ciblé à toutE42.')
add('S9','https://pmc.ncbi.nlm.nih.gov/articles/PMC9108366/','Mechanisms of Kwashiorkor-Associated Immune Suppression','Michael et coll., revue internationale','2022','michael2022.xml','Introduction, kwashiorkor/marasme, immunité innée/adaptative et conclusion ciblée','Études humaines et modèles souris/porcs','Revue contient erreurs de signes/seuils anthropométriques et généralités thérapeutiques non retenues. Pas fondement de recommandations américaines, de probiotiques routiniers ni d’un test génétique E42. Références microbiome anciennes non reprises sans critique, rétraction2023 retrouvée.','Immunité et barrière sont perturbées ; nombres leucocytaires normaux n’assurent pas fonction normale. Données de dendritiques/TetB et modèles animaux distinctes. Génétique de susceptibilité hypothétique, pas mutation définissant E42 ni maladie mendélienne unique. Traiter infection/renutrition, ne pas confondre restauration anthropométrique et récupération immunitaire complète.')
add('S10','https://pmc.ncbi.nlm.nih.gov/articles/PMC9589698/','IPNA recommendations : steroid-sensitive nephrotic syndrome','Trautmann et coll., IPNA, équipes européennes/internationales','2022','ipna2022.xml','Tableau1 définitions, clinical assessment et diagnosticwork-up initial','Enfant œdémateux, diagnostic différentiel','Pas traitement immunosuppresseur prescrit dansE42 ; seuils urinaires sont ceux du syndrome néphrotique, pas définition nutritionnelle.','Un œdème déclive justifie recherche de syndrome néphrotique ; protéinurie/créatininurie≥200mg/mmol avec albumine<30g/l ou œdème si albumineabsente. Dépistage bandelette puis quantification, de préférence premièreurine ; autres causes hépatiques,cardiaques,digestives,malnutrition et fuitecapillaire sont considérées.')
add('S11','https://pmc.ncbi.nlm.nih.gov/articles/PMC2926439/','Clinical practice: Protein-losing enteropathy in children','Braamskamp et coll., Pays-Bas','2010','protein-losing2010.xml','Résumé,introduction/pathogenèse/tableau1, quandévoquer, diagnostic alpha1-antitrypsine','Enfants, pertes digestives protéiques','Revueancienne pour raisonnement différentiel ; pas incidence ni précision universelle de scintigraphie reprises. Valeurs test dépendantes contexte/laboratoire.','Œdème et hypoalbuminémie peuvent venir pertesdigestives, pertesrénales, défautsynthèse ou inflammation/dilution. Alpha1-antitrypsine fécale et clairance peuvent rechercher perteintestinale, sans localiser site et moinsutile si fuitegastrique ; rechercher cause plutôt que conclureE42 suralbumine basse.')
add('S12','https://amiko.oddb.org/fr/fi?gtin=7680665530017','FI Amoxicilline axapharm200mg/4ml, suspensionorale','Swissmedic/AIPS via AmiKo','Octobre2024','fi-amoxi-suspension.html','Indications, dose/forme, rein, sécurité/interactions, grossesse/allaitement et miseàjour ; Swisspeddose annexe distincte','Enfants≤40kg, adultes>40kg distingués','Pas indication propre E42 ni protocole complet de sepsis. Le premier produit dispersible lu est inadapté≤40kg et a été écarté, pas copié comme suspension.','50mg/ml aprèsreconstitution ; enfant≤40kg50–100mg/kg/j en3–4prises,max2000mg/j,max50mg/kgparprise. Nouveau-né/prématuré parentéral en règle, oralauplus tôt8jours. Rein≤40kgparentéral selonFI ; >40kgmax500q12hsiClCr10–30,max500q24hsi<10. Allergies/mononucléose, diarrhéegrave/réactionspeau, cristallurie, méthotrexate/allopurinol/anticoagulants. Agiter, suspension10joursmax ; FIallaitement défavorable, grossesseprudence. DoseMSF100mg/kg/j2prises n’est pas fréquenceFI3–4.')
add('S13','https://amiko.oddb.org/fr/fi?gtin=7680256360580','FI Benerva comprimés100/300mg et ampoule100mg/ml','Swissmedic/AIPS via AmiKo','Avril2019','fi-benerva.html','TexteFI : composition, indications, doses, voies, précautions/interactions et grossesse/allaitement','Adultes et adolescents dès12ans ; usage pédiatrique non étudié systématiquement','Pas dose de renutrition infantile autorisée par cette FI ; consultation2026 ne renouvelle pas version2019. Ne pas transposer dose adulte IV300mg.','Prophylaxie100mgunjoursurdeux oral ; traitement100mg/j modéré,200–300mg/jgraveoral. Gravescarences parentéraljusqu200mg/j, IVtrèslente/hospitalière avec risqueanaphylactoïde, voieorale préférée si possible. Antacidesdiminuentabsorption,5fluorouracileantagoniste ; grossesse/allaitement dosesBenerva seulementnécessitéabsolue, pas confondrebesoinsquotidiens. Coenzyme métabolismeglucidique, rôleenrenutrition.')
add('S14','https://openstax.org/books/anatomy-and-physiology-2e/pages/23-5-the-small-and-large-intestines','The small and large intestines : normal','OpenStax','2e, page servie2026','openstax-intestine.html','Anatomiegrêle, histologieplis/villosités/microvillosités, figure23.19 et créditMichigan','Science normale, pas soins','Manuel américain pour normal seulement, aucune recommandation américaine. Longueurs, rapports d’épaisseur et surface globale approximatifs non nécessaires donc non copiés.','Duodénum,jéjunum,iléon ; replis,villosités et bordure augmentent absorption. Villosité contient capillairessanguins et chylifère ; sucres/acidesaminés verssang, lipides selonvoies verslymphe. Cryptes et cellulesépithéliales soutiennent barrière ; image normale ne montre pas lésionE42. Figure:micrographiesMichigan©2012, grossissementsd’origine noncalibrationécran.')
add('S15','https://data.unicef.org/resources/jme/','Joint Child Malnutrition Estimates : key findings2025','UNICEF/OMS/BanqueMondiale','2025, données2024','jme2025.pdf','p1–2 : chiffres, définition, portéeprévalence et limites','Moins5ans dansmonde','Pas incidenceannuelle, pas estimation des seulsœdèmes/formesmixtesE42, pas incidence suisse. Anciennesestimations remplacées.','2024 :42,8millions6,6%avecémaciation, dont12,2millionssévère. Estimationsprévalencebaséesenquêtes necomptentpas toustousépisodesannuels ; formescombinées pasd’estimationglobalecommune. Ne pas utiliser chiffrecomme risqueindividuelE42.')
add('S16','https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','PROFILES2017','CIMS Suisse','2017','/workspace/medina-source-cache/C85/profiles2017-official.pdf','EPAévaluationnutritionnellep18 ; SSPœdème/pertepoids ; situationsenfance croissance/alimentation','Formation suisse','Objectifspédagogiques, pas correspondanceofficielleE42 ouprévisionquestionfédérale.','Évaluerétatnutritionnel, pertepoids,œdème, croissance et alimentationinfantile ; observer, mesurer, explorerurgence et contexte. Raisonner ensituationplutôtque mémoriserun code.')
add('S17','https://pmc.ncbi.nlm.nih.gov/articles/PMC7619504/','GASTROSAM oral: WHO-ORS versus ReSoMal','Maitland et coll., Afrique/équipesbritanniques, MSF','Mars2026','gastrosam-oral2026.xml','Résumé,méthodes,sélection, résultats/natrémie, discussion et limites','415enfants6mois–12ans, diarrhée/déshydratation,24avecœdème','Essaisupériorité,pas preuved’équivalenceuniverselle ; forte surveillance, peuformesœdémateuses, pascholéra ; mélangefactorielliquidesIV dansstrateA.','PasdifférencesignificativevariationNaà24h(critèreprimaire), mortalité28j19vs24sansdifférenceétablie, pas surchargeobservée. HyponatrémiesplusfréquentesavecReSoMalà8h. Cesdonnées soutiennent réexamenguides, sans attribuer415casE42 ni transférerabsenceévénementà garantie100%/domicile.')
add('S18','https://pmc.ncbi.nlm.nih.gov/articles/PMC7617792/','GASTROSAM : intravenous rehydration','Maitland et coll., Afrique/équipesbritanniques','Juin2025','gastrosam-iv2025.xml','Résumé,méthodes/sélection et discussion/limites ciblées','272enfants6mois–12ans, diarrhée/déshydratationsévère,11avecœdème','Faibleeffectifœdémateux,mortalitéinférieureprévue doncpuissancelimitée. Texteabstractcomportecertainschiffres/coquillesincohérents ; pasrepriscommecomparaisonnumériquefinale.','Comparaisonstratégiesorales/IV sansdifférencemortalité96h établie ni surchargeobservée ; forte surveillancequipecherche réduit généralisation. Ne pasinterdiretouteIV ni prescrire100ml/kg universelàtoutE42 ; protocolehospitalier adaptéàperfusionetgravité.')
add('S19','https://pmc.ncbi.nlm.nih.gov/articles/PMC7619270/','Intravenous rehydration : systematic review and meta-analysis','Dewez et coll., équipesbritanniques/africaines','Septembre2026','fluid-review2026.xml','Résumé,méthodeséligibilité, résultats et discussion/limites ciblés','Troisessais,484enfants, malnutritiongrave/gastroentérite','Unseulessaicritèresstricts,troisstratégieshétérogènes ; sousgroupekwashiorkor nonisolable, pasautorisationdelibérerprescriptionindividuelle.','Ratiomortalitéestimé0,71intervalle0,46–1,10 ne prouvepasréduction54% ; aucunesurchargeobservée n’exclutpasrareté/risquesindividuels. Donnéesmotiventrevuepratique, pasnouvelleconsigneOMS.')
